contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: amount to send initially to Put, lockTime to set, and amount to attempt to collect.
    function run(uint putLock, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance");

        // Initialize: ensure MinSum is zero and contract not initialized (fresh c is deployed by harness)
        // Use Put to deposit funds into c for this test caller (InvMutTest is msg.sender for c calls)
        // Record before-values
        (uint beforeUnlock, uint beforeBalance) = accOf(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put with value putAmount
        c.Put{value: putAmount}(putLock);

        // Read mid-values after Put
        (uint midUnlock, uint midBalance) = accOf(address(this));
        uint midContractBal = address(c).balance;

        // Ensure Put had the expected observable effect: balances increased by putAmount
        // If putAmount overflows in contract addition it would revert; here we only assert general rule after Collect.

        // Advance: try Collect of collectAmount and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = accOf(address(this));
        uint afterContractBal = address(c).balance;

        // The property: if Collect did NOT revert and the contract balance decreased by collectAmount,
        // then the holder's recorded balance must have decreased by exactly collectAmount as well.
        // Also require that the change in contract balance equals the change in holder balance.
        // This asserts the invariant that successful Collect transfers funds consistently.
        assert(collectReverted || (
            // when not reverted, the holder's balance decreased by collectAmount and contract balance decreased same
            afterBalance + collectAmount == midBalance
            && midContractBal == afterContractBal + collectAmount
            && (midBalance - afterBalance) == (midContractBal - afterContractBal)
        ));
    }

    // helper to read Acc[msg.sender] via public getter Acc(address) returns (uint unlockTime, uint balance)
    function accOf(address a) internal view returns (uint unlockTime, uint balance) {
        // The auto-generated getter for public mapping Acc returns the struct members
        return c.Acc(a);
    }

    receive() external payable {}
}

