contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to deposit some funds via Put, then attempt Collect of amount am.
    // Parameters:
    //   uint putLock - lock time passed to Put
    //   uint putAmt  - amount of wei to send with Put
    //   uint am      - amount requested in Collect
    // Note: address(this) must have at least putAmt wei when run is called.
    function run(uint putLock, uint putAmt, uint am) public payable {
        require(address(this).balance >= putAmt, "insufficient balance for Put");

        // Read balances before any action
        uint beforeAccBal = c.Acc(address(this)).balance;
        uint beforeContractBal = address(c).balance;

        // Perform Put with value putAmt
        c.Put{value: putAmt}(putLock);

        // Read balances after Put, before Collect
        uint afterPutAccBal = c.Acc(address(this)).balance;
        uint afterPutContractBal = address(c).balance;

        // sanity: afterPutAccBal should be at least beforeAccBal (checked by Put properties)
        // Now attempt Collect(am). We catch revert to observe behavior.
        bool reverted;
        (reverted) = (false);
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after Collect
        uint afterCollectAccBal = c.Acc(address(this)).balance;
        uint afterCollectContractBal = address(c).balance;

        // If Collect did not revert, then by contract logic either it did nothing (conditions false)
        // or it transferred am and decreased stored balance by am. We assert the general rule:
        // If not reverted AND afterCollectAccBal != afterPutAccBal then:
        //    afterCollectAccBal == afterPutAccBal - am  (stored balance decreased exactly by am)
        //    and afterCollectContractBal + am <= afterPutContractBal  (contract lost at least am wei)
        // Otherwise (reverted or no change) the stored and contract balances stay the same as after Put.
        assert(
            (
                (!reverted && afterCollectAccBal < afterPutAccBal) ?
                    (
                        // stored balance decreased exactly by am
                        (afterCollectAccBal + am == afterPutAccBal)
                        // contract's balance decreased by at least am (use + to avoid underflow in assert)
                        && (afterCollectContractBal + am <= afterPutContractBal)
                    )
                :
                    // otherwise stored and contract balances unchanged
                    (afterCollectAccBal == afterPutAccBal && afterCollectContractBal == afterPutContractBal)
            )
        );
    }

    // allow receiving ETH for the test harness
    receive() external payable {}
}

