contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will set MinSum and put some funds, then try Collect and assert consistency
    function run(uint initialMin, uint lockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for put");
        // initialize MinSum and Log only allowed before Initialized, so leave intitalized false
        c.SetMinSum(initialMin);

        // Record balances before Put
        uint beforeContractBal = address(c).balance;
        (uint beforeAccUnlock, uint beforeAccBal) = c.Acc(address(this));

        // Call Put sending putAmount wei
        c.Put{value: putAmount}(lockTime);

        // After Put, try to Collect collectAmount. We must record state before calling Collect
        uint midContractBal = address(c).balance;
        (uint midAccUnlock, uint midAccBal) = c.Acc(address(this));

        // Attempt Collect and record whether it reverted
        bool reverted;
        // Need to ensure this call has enough gas and doesn't depend on msg.value; Collect is payable but uses provided _am
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBal = address(c).balance;
        (uint afterAccUnlock, uint afterAccBal) = c.Acc(address(this));

        // If Collect did not revert, then it must have transferred exactly collectAmount out of the contract
        // and decreased the recorded Acc.balance by exactly collectAmount. Express that as the invariant.
        assert(reverted || (midContractBal - afterContractBal == collectAmount && midAccBal - afterAccBal == collectAmount));
    }

    receive() external payable { }
